        if (j == p.length()) result = i == s.length();
        else {
            boolean first = i < s.length() && (p.charAt(j) == s.charAt(i) || p.charAt(j) == '.');
            if (j + 1 < p.length() && p.charAt(j + 1) == '*')
                result = match(s, p, i, j + 2) || (first && match(s, p, i + 1, j));
            else result = first && match(s, p, i + 1, j + 1);
        }
